-- Module: facility — Rooms & Facilities

CREATE SCHEMA IF NOT EXISTS facility;
COMMENT ON SCHEMA facility IS 'Rooms & Facilities: Rooms (classrooms, labs, exam halls), the facilities they offer and the assets they hold.';

CREATE TABLE facility.facility (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid NOT NULL,
    code varchar(30) NOT NULL,
    name varchar(120) NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    sort_order integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_facility PRIMARY KEY (id),
    CONSTRAINT uq_facility_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE facility.facility IS 'Facility type available in rooms (projector, smart board, AC...).';
COMMENT ON COLUMN facility.facility.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN facility.facility.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN facility.facility.institution_id IS 'Institution.';
COMMENT ON COLUMN facility.facility.code IS 'Facility code.';
COMMENT ON COLUMN facility.facility.name IS 'Facility name.';
COMMENT ON COLUMN facility.facility.is_active IS 'Whether in use.';
COMMENT ON COLUMN facility.facility.created_at IS 'Row creation time.';
COMMENT ON COLUMN facility.facility.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN facility.facility.updated_at IS 'Last update time.';
COMMENT ON COLUMN facility.facility.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN facility.facility.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN facility.facility.row_version IS 'Optimistic-locking version.';
COMMENT ON COLUMN facility.facility.sort_order IS 'Display order.';

CREATE TABLE facility.room (
