COMMENT ON COLUMN facility.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN facility.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN facility.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN facility.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN facility.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN facility.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN facility.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN facility.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN facility.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN facility.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN facility.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN facility.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN facility.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE facility.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE facility.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON facility.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE facility.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_facility_operation PRIMARY KEY (id),
    CONSTRAINT ck_facility_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
