COMMENT ON COLUMN facility.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN facility.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN facility.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN facility.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN facility.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN facility.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN facility.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN facility.operation.started_at IS 'Start time.';
COMMENT ON COLUMN facility.operation.finished_at IS 'End time.';
COMMENT ON COLUMN facility.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN facility.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN facility.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN facility.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
